/**
 * AutoEQ preset library (read-only, loaded on first use).
 *
 * The data file is generated by `scripts/import-autoeq.mjs` from
 * https://github.com/jaakkopasanen/AutoEq (MIT). Each entry is one measured
 * headphone with a ten-band fixed EQ: `{ n: name, s: source, f: form,
 * p: preamp, g: [10 gains] }` on the same bands the plugin's equalizer uses.
 *
 * @module dsh-music-panel/eq-presets
 */

import { readFile } from 'node:fs/promises'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const DATA_FILE = join(dirname(fileURLToPath(import.meta.url)), 'data', 'autoeq-presets.json')

/** @type {null | { generated: string, bands: number[], presets: any[], sources: { id: string, count: number }[] }} */
let loaded = null
let loading = null

/** Stable id for one entry; survives re-imports as long as the measurement does. */
export function eqPresetId(entry) {
  return `${entry.s}::${entry.f}::${entry.n}`
}

function withSources(payload) {
  const counts = new Map()
  for (const entry of payload.presets) counts.set(entry.s, (counts.get(entry.s) || 0) + 1)
  const sources = [...counts.entries()]
    .map(([id, count]) => ({ id, count }))
    .sort((a, b) => b.count - a.count || a.id.localeCompare(b.id))
  return Object.assign({}, payload, { sources })
}

/**
 * Load the dataset once. Missing or corrupt data rejects; the route turns that
 * into a 500 instead of taking the whole server down.
 */
export function loadEqPresets() {
  if (loaded !== null) return Promise.resolve(loaded)
  if (loading === null) {
    loading = readFile(DATA_FILE, 'utf8')
      .then((text) => withSources(JSON.parse(text)))
      .then((payload) => {
        loaded = payload
        loading = null
        return payload
      })
      .catch((error) => {
        loading = null
        throw error
      })
  }
  return loading
}

/**
 * Case-insensitive AND search over model names, ranked so that "starts with"
 * beats "contains". Empty queries return the head of the list (the UI only
 * asks for a search once the user types).
 */
export function searchEqPresets(payload, query, options = {}) {
  const limit = Math.min(100, Math.max(1, Number(options.limit) || 40))
  const source = String(options.source || '')
  const text = String(query || '').trim().toLowerCase()
  const tokens = text.split(/\s+/).filter(Boolean)
  const hits = []
  for (const entry of payload.presets) {
    if (source !== '' && entry.s !== source) continue
    const name = String(entry.n).toLowerCase()
    if (tokens.length === 0) {
      hits.push({ entry, score: 2 })
      continue
    }
    let score = name.startsWith(text) ? 0 : 2
    let matched = true
    for (const token of tokens) {
      const at = name.indexOf(token)
      if (at < 0) {
        matched = false
        break
      }
      if (score > 0 && (at === 0 || /[\s\-/(]/.test(name[at - 1]))) score = 1
    }
    if (matched) hits.push({ entry, score })
  }
  hits.sort((a, b) => a.score - b.score || a.entry.n.localeCompare(b.entry.n) || a.entry.s.localeCompare(b.entry.s))
  return hits.slice(0, limit).map((hit) => hit.entry)
}

/** Shape one entry for the client (adds the stable id and readable fields). */
export function eqPresetRow(entry) {
  return {
    id: eqPresetId(entry),
    name: entry.n,
    source: entry.s,
    form: entry.f,
    preamp: entry.p,
    bands: entry.g,
  }
}
